mode = (sys.argv[1] if len(sys.argv) > 1 else "dry").strip()
if mode not in ("columns", "dry", "apply"):
    raise SystemExit("режим: columns | dry | apply")
dry = mode == "dry"
factory = build_references_uow_factory(build_engine(os.environ["ERP_DATABASE_URL"]))
now = moscow_now()

if mode == "columns":
    with factory() as uow:
        own = custom_columns(TechOperationTab.MATERIAL, uow)
        for name in NEED_COLUMNS:
            if name in own:
                print(f"   уже есть: «{name}»")
                continue
            print(f"   столбец «{name}» заведён: {add_column(ColumnCommand(tab=TechOperationTab.MATERIAL, name=name, actor=ACTOR, now=now), uow)} записей")
        uow.commit()
    raise SystemExit(0)

with factory() as uow:
    missing = [name for name in NEED_COLUMNS if name not in custom_columns(TechOperationTab.MATERIAL, uow)]
if missing:
    raise SystemExit("нет столбцов БД.МАТ: " + ", ".join(missing) + " — сначала режим columns (после backup-now)")


def run(items, label, *, create):
    """Step 1 of a group: the sheet columns through import_rows. Returns False when the group stopped."""
    rows = [ImportRowIn(fields=i["fields"], old=i["old"]) for i in items if len(i["fields"]) > 1]

    def call(dry_run):
        return import_rows("mat", factory(), rows, ACTOR, now, dry_run=dry_run, source="erp").model_dump()

    if not rows:
        print(f"== {label}: ячеек листа нет")
        return True
    data = call(True)
    # a fill must find its row and be refused for nothing; a new row must not touch an existing one — otherwise the group stops
    if (data["created"] and not create) or (create and data["updated"]) or (data["refused"] and not create):
        print(f"== {label}: СТОП — создано {len(data['created'])}, обновлено {len(data['updated'])}, отказов {len(data['refused'])}; ничего не записано")
        for item in data["refused"][:20]:
            print("   отказ:", item)
        return False
    if not dry:
        data = call(False)
    print(f"== {label}: строк {len(rows)} → создано {len(data['created'])}, обновлено {len(data['updated'])}, "
          f"без изменений {data['unchanged']}, отказ {len(data['refused'])}")
    for item in data["refused"][:20]:
        print("   отказ:", item)
    return True


def own_columns(items, label):
    """Step 2: «Цена, ₽», «Дата цены», «Ссылка на покупку», «Фасовка» — an edit of the record, old=\"\" (another value — a refusal)."""
    done = same = refused = missing = 0
    with factory() as uow:
        by_name = {str(r.fields.get("Наименование", "")).strip(): r.id
                   for r in uow.tech_operations.list(tab=TechOperationTab.MATERIAL, query="", limit=100_000)}
    for item in items:
        if not item["extra"]:
            continue
        name = item["fields"]["Наименование"]
        record_id = by_name.get(name)
        if record_id is None:
            missing += 1
            continue
        with factory() as uow:
            record = uow.tech_operations.get(record_id)
            edits = tuple(FieldEdit(key, "", value) for key, value in item["extra"].items()
                          if str(record.fields.get(key, "")).strip() != value)
            if not edits:
                same += 1
                continue
            try:
                before, _ = _edit_in(record_id, edits, now, uow)
            except (StaleRecordError, ReferenceValidationError, LookupError) as error:
                refused += 1
                print(f"   отказ (столбцы): {name} ({error})")
                continue
            _audit("references.tech_record_edited", ACTOR, now, {"record_id": str(before.id), "tab": before.tab.value,
                   "fields": [edit.field for edit in edits], "reason": "термоусадка КВТ и REXANT, Электромонтаж: цена, ссылка, фасовка (25.10.2026)"}, uow)
            if not dry:
                uow.commit()
            done += 1
    print(f"   {label}, столбцы цены: {'проверено' if dry else 'записано'} {done}, уже так {same}, отказ {refused}, "
          f"строки ещё нет (появится при записи) {missing}")


ok1 = run(PAYLOAD["fill"], "1 дозаполнение пустых ячеек существующих строк", create=False)
ok2 = run(PAYLOAD["create"], "2 новые артикулы КВТ / Rexant (Электромонтаж)", create=True)
if ok1:
    own_columns(PAYLOAD["fill"], "1")
if ok2:
    own_columns(PAYLOAD["create"], "2")
print("ИТОГО", "(проверка, ничего не записано)" if dry else "(записано)")
